-- Frozen onCreate schema from f377fbf (v20); synthetic fixture, no user data.
CREATE TABLE transactions (id INTEGER PRIMARY KEY, unique_key TEXT UNIQUE NOT NULL, occurred_at INTEGER NOT NULL, received_at INTEGER NOT NULL, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, merchant TEXT NOT NULL, category TEXT NOT NULL, source TEXT NOT NULL, message_hash TEXT, payment_source_id INTEGER, card_last4 TEXT, kind TEXT NOT NULL DEFAULT 'expense', destination_source_id INTEGER, note TEXT, user_edited INTEGER NOT NULL DEFAULT 0, needs_review INTEGER NOT NULL DEFAULT 0, fee_parent_id INTEGER);
CREATE INDEX transaction_date ON transactions(occurred_at DESC);
CREATE INDEX transaction_message_hash ON transactions(message_hash, occurred_at);
CREATE TABLE excluded_messages (unique_key TEXT PRIMARY KEY);
CREATE TABLE recurring (id INTEGER PRIMARY KEY, merchant TEXT NOT NULL, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, next_due TEXT NOT NULL, last_alert_date TEXT, cycle TEXT NOT NULL DEFAULT 'monthly', kind TEXT NOT NULL DEFAULT 'subscription', total_count INTEGER, paid_count INTEGER NOT NULL DEFAULT 0, remind_days INTEGER NOT NULL DEFAULT 1, match_text TEXT, payment_source_id INTEGER, last_paid_date TEXT, status TEXT NOT NULL DEFAULT 'active', due_day INTEGER, needs_review INTEGER NOT NULL DEFAULT 0, hint_key TEXT, last_completion_hash TEXT, UNIQUE(merchant, amount_minor, currency));
CREATE TABLE payment_sources (id INTEGER PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, last4 TEXT, parent_source_id INTEGER, display_name TEXT, archived INTEGER NOT NULL DEFAULT 0, reviewed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE source_aliases (identity TEXT PRIMARY KEY, payment_source_id INTEGER NOT NULL);
CREATE TABLE budgets (id INTEGER PRIMARY KEY, month TEXT NOT NULL, category TEXT NOT NULL, currency TEXT NOT NULL, amount_minor INTEGER NOT NULL, UNIQUE(month, category, currency));
CREATE TABLE balance_snapshots (id INTEGER PRIMARY KEY, payment_source_id INTEGER NOT NULL, currency TEXT NOT NULL, balance_minor INTEGER NOT NULL, occurred_at INTEGER NOT NULL, received_at INTEGER NOT NULL, source TEXT NOT NULL, unique_key TEXT UNIQUE NOT NULL);
CREATE INDEX balance_snapshot_order ON balance_snapshots(payment_source_id,currency,occurred_at DESC,received_at DESC);
CREATE TABLE merchant_rules (id INTEGER PRIMARY KEY, match_text TEXT NOT NULL COLLATE NOCASE UNIQUE, category TEXT NOT NULL, ignored INTEGER NOT NULL DEFAULT 0);
CREATE TABLE budget_plans (id INTEGER PRIMARY KEY, name TEXT NOT NULL, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, cycle TEXT NOT NULL, anchor_date TEXT NOT NULL, duration_days INTEGER NOT NULL);
CREATE TABLE budget_plan_categories (plan_id INTEGER NOT NULL, category TEXT NOT NULL, PRIMARY KEY(plan_id,category));
CREATE TABLE assets (id INTEGER PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, value_minor INTEGER NOT NULL, currency TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE debts (id INTEGER PRIMARY KEY, name TEXT NOT NULL, direction TEXT NOT NULL, original_minor INTEGER NOT NULL, remaining_minor INTEGER NOT NULL, currency TEXT NOT NULL, due_date TEXT);
CREATE TABLE own_handles (handle TEXT PRIMARY KEY);
CREATE TABLE capture_evidence(unique_key TEXT PRIMARY KEY, transaction_id INTEGER NOT NULL, message_hash TEXT, normalized_hash TEXT, reference_hash TEXT, source TEXT NOT NULL, sender TEXT, received_at INTEGER NOT NULL, direction TEXT, encrypted_body TEXT);
CREATE INDEX evidence_transaction ON capture_evidence(transaction_id);
CREATE INDEX evidence_hash ON capture_evidence(message_hash,received_at);
CREATE TABLE commitment_suggestions(hint_key TEXT PRIMARY KEY, merchant TEXT NOT NULL, kind TEXT NOT NULL, amount_minor INTEGER NOT NULL, total_count INTEGER, estimated_date TEXT NOT NULL, explanation TEXT NOT NULL, sender TEXT, received_at INTEGER NOT NULL, encrypted_body TEXT, status TEXT NOT NULL DEFAULT 'pending', currency TEXT NOT NULL DEFAULT 'EGP', cycle TEXT NOT NULL DEFAULT 'monthly', date_exact INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS commitment_observations(message_key TEXT PRIMARY KEY, hint_key TEXT NOT NULL, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, due_date TEXT NOT NULL, sender TEXT, received_at INTEGER NOT NULL, encrypted_body TEXT);
CREATE INDEX IF NOT EXISTS commitment_observation_order ON commitment_observations(hint_key,received_at DESC);
CREATE TABLE transaction_archive(id INTEGER PRIMARY KEY, original_id INTEGER NOT NULL, reason TEXT NOT NULL, archived_at INTEGER NOT NULL, payload TEXT NOT NULL);
ALTER TABLE recurring ADD COLUMN origin_transaction_id INTEGER;
CREATE TABLE IF NOT EXISTS dismissed_patterns (pattern_key TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS repair_log (id INTEGER PRIMARY KEY, ran_at INTEGER NOT NULL, version INTEGER NOT NULL, promotions INTEGER NOT NULL, duplicates INTEGER NOT NULL, own_transfers INTEGER NOT NULL, moved_minor INTEGER NOT NULL, fees_minor INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reimbursements (income_id INTEGER PRIMARY KEY, expense_id INTEGER NOT NULL, amount_minor INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reimbursement_expense ON reimbursements(expense_id);
ALTER TABLE recurring ADD COLUMN last_paid_due TEXT;
PRAGMA user_version=20;
